def min_remove_to_make_valid(s):
    stack = []
    to_remove = set()

    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                to_remove.add(i)

    to_remove.update(stack)

    return ''.join(ch for i, ch in enumerate(s) if i not in to_remove)

